<div class="page-header"><div><span class="eyebrow">BUILD A CLEARER WAY FORWARD</span><h1><?= e($config['label']) ?></h1><p>Thoughtful content. Useful practice. A clear next step for every learner.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= e(route_url('/admin/content/' . ($resource) . '/new')) ?>"><?= icon('plus',16) ?> Add <?= e(strtolower($config['singular'])) ?></a></div></div><?php require ROOT.'/app/Views/components/admin-content-tabs.php'; ?>
<div class="toolbar"><form action="<?= e(route_url('/admin/content/' . ($resource))) ?>" class="filter-form" method="get"><div class="search-field"><?= icon('search',17) ?><input name="q" type="search" value="<?= e($_GET['q']??'') ?>" placeholder="Find <?= e(strtolower($config['label'])) ?>…" aria-label="Search <?= e($config['label']) ?>" maxlength="150"></div><?php if(isset($config['fields']['status'])): ?><select class="select" name="status" aria-label="Publication status"><option value="">Every status</option><?php foreach(['draft','published','archived'] as $s): ?><option value="<?= $s ?>" <?= ($_GET['status']??'')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select><?php endif; ?><button class="btn btn-secondary" type="submit"><?= icon('filter',14) ?> Apply filters</button></form><span class="results-label"><?= $total ?> records</span></div>
<section class="card table-card"><?php if($rows): ?><div class="table-responsive"><table class="data-table"><thead><tr><th><?= e($config['singular']) ?></th><th><?= isset($config['fields']['status'])?'Status':(isset($config['fields']['active'])?'Availability':'Details') ?></th><th>Reference</th><th style="text-align:right">Actions</th></tr></thead><tbody><?php foreach($rows as $row):$id=$row[$config['pk']??'id'];$label=$row['title']??$row['name']??$row['label']??'Level '.$id; ?><tr><td><strong><a href="<?= e(route_url('/admin/content/' . ($resource) . '/' . ((int)$id) . '/edit')) ?>"><?= e($label) ?></a></strong><small><?= e(mb_strimwidth($row['description']??$row['instructions']??($row['minimum_xp']??'') . ($resource==='levels'?' minimum XP':''),0,100,'…')) ?></small></td><td><?php if(isset($row['status'])): ?><?= badge($row['status']) ?><?php elseif(isset($row['active'])): ?><?= badge($row['active']?'active':'archived') ?><?php elseif(isset($row['position'])): ?><span>Position <?= (int)$row['position'] ?></span><?php else: ?><span><?= e($row['metric']??($resource==='levels'?'Level '.$id:'Configured')) ?></span><?php endif; ?></td><td><span class="mono">#<?= (int)$id ?></span></td><td><div class="table-actions"><a class="icon-button" href="<?= e(route_url('/admin/content/' . ($resource) . '/' . ((int)$id) . '/edit')) ?>" title="Edit" aria-label="Edit <?= e($label) ?>"><?= icon('pen',16) ?></a><?php if($resource==='paths'): ?><button class="icon-button" data-api-button="<?= e(route_url('/api/admin/paths/' . ((int)$id) . '/duplicate')) ?>" data-confirm="Create a complete draft copy of this path, its lessons and assessments? Learner progress is not copied." title="Duplicate path" aria-label="Duplicate <?= e($label) ?>"><?= icon('copy',16) ?></button><?php endif; ?><?php if(isset($row['status']) && $row['status']!=='archived'): ?><button class="icon-button" data-api-button="<?= e(route_url('/api/admin/content/' . ($resource) . '/' . ((int)$id) . '/archive')) ?>" data-confirm="Archive this content? It will no longer be available to learners. Existing assessment and progress records are preserved." title="Archive" aria-label="Archive <?= e($label) ?>"><?= icon('folder',16) ?></button><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php pagination($total); ?><?php else: emptyState($config['icon'],'Something useful starts here.','No records match these filters yet. Add your first '.strtolower($config['singular']).' or try another search.','/admin/content/'.$resource.'/new','Create '.strtolower($config['singular']));endif; ?></section>
